// Fetch Maestro dialog traces z Langfuse za posledních 6h pro evaluaci.
//
// Cíl: měřit USP integrity (multi-turn coherence, retrieval recall, answer faithfulness)
// a flagnout regrese před tím, než se promítnou do user experience.
//
// Doplňuje WF_LANGFUSE_PERFORMANCE_REVIEW (denní generic review) — toto je
// Insight-specific eval na úrovni Maestro/Ragnarok dialogů.

const langfuseHost = $env.LANGFUSE_HOST || 'http://langfuse-web:3000';
const langfusePublicKey = $env.LANGFUSE_PUBLIC_KEY;
const langfuseSecretKey = $env.LANGFUSE_SECRET_KEY;

if (!langfusePublicKey || !langfuseSecretKey) {
  return { json: { error: 'Langfuse credentials missing — eval skipped' } };
}

const windowHours = 6;
const startTime = new Date(Date.now() - windowHours * 60 * 60 * 1000).toISOString();

return {
  json: {
    langfuseHost,
    auth: Buffer.from(`${langfusePublicKey}:${langfuseSecretKey}`).toString('base64'),
    startTime,
    windowHours,
  }
};

// Score traces na 3 USP-kritické dimenze:
//  1. multi_turn_coherence — turn-2+ navazuje na turn-1?
//  2. retrieval_recall — Ragnarok kb_chunks count > 0 pro KB-relevantní queries?
//  3. governance_compliance — žádné porušení Tao constraints (warmth floor, no-punitivity)?
//
// Skutečná LLM-based eval (semantic coherence) by vyžadovala další API call —
// pro MVP používáme heuristiky + counts. Detailní semantic eval = future ticket.

const traces = $input.item.json.data || [];
const totalTraces = traces.length;

let coherenceFlags = 0;
let zeroRetrievalCount = 0;
let governanceViolations = 0;
let maestroUsedCount = 0;
let contextEnabledFalse = 0;

for (const trace of traces) {
  const meta = trace.metadata || {};
  const obs = trace.observations || [];

  if (meta.provider === 'maestro' || meta.used_maestro_dialog === true) {
    maestroUsedCount++;
  }

  if (meta.kb_retrieval_chunks === 0) {
    zeroRetrievalCount++;
  }

  // Multi-turn coherence: pokud má více turnů ale druhý nereferuje předchozí kontext
  if (obs.length > 1) {
    const lastObs = obs[obs.length - 1];
    if (lastObs?.output && typeof lastObs.output === 'string' && lastObs.output.length < 50) {
      coherenceFlags++;
    }
  }

  if (meta.governance_tao_applied === 0) {
    governanceViolations++;
  }

  if (meta.context_enabled === false || meta.maestro_context_disabled) {
    contextEnabledFalse++;
  }
}

const report = {
  signal: 'insight_dialog_eval',
  window_hours: $('Prepare Eval Input').item.json.windowHours,
  total_traces: totalTraces,
  maestro_used_count: maestroUsedCount,
  metrics: {
    coherence_flags: coherenceFlags,
    zero_retrieval_count: zeroRetrievalCount,
    governance_violations: governanceViolations,
    context_enabled_false: contextEnabledFalse,
  },
  health: {
    coherence_ratio: totalTraces > 0 ? 1 - (coherenceFlags / totalTraces) : 1,
    retrieval_ratio: totalTraces > 0 ? 1 - (zeroRetrievalCount / totalTraces) : 1,
    governance_ratio: totalTraces > 0 ? 1 - (governanceViolations / totalTraces) : 1,
  },
  alerts: [],
};

// Alert thresholds
if (totalTraces >= 10) {
  if (report.health.coherence_ratio < 0.7) {
    report.alerts.push({ severity: 'high', metric: 'coherence', message: 'Multi-turn coherence < 70% — Maestro dialog management může mít regresi.' });
  }
  if (report.health.governance_ratio < 0.9) {
    report.alerts.push({ severity: 'critical', metric: 'governance', message: 'Tao governance applied < 90% — brain wiring je rozpojený.' });
  }
  if (contextEnabledFalse > 0) {
    report.alerts.push({ severity: 'critical', metric: 'context_enabled', message: 'Maestro CONTEXT_ENABLED=false v některých runech — USP regrese.' });
  }
}

return { json: report };

// Pokud jsou alerts → zaloguj jako improvement_proposal pro WF_SELF_LEARNING_LOOP.
// Bez alertů → idle, jen audit trail v ai_runs.

const report = $input.item.json;
const alerts = report.alerts || [];

if (alerts.length === 0) {
  return { json: { ok: true, status: 'no_regression', report } };
}

const postgrestUrl = $env.AISHA_POSTGREST_URL || $env.POSTGREST_URL;
const serviceKey = $env.AISHA_SERVICE_KEY || $env.POSTGREST_SERVICE_TOKEN;

const topAlert = alerts.find(a => a.severity === 'critical') || alerts[0];

const rpcBody = {
  p_agent_slug: 'insight-dialog-eval',
  p_title: `Insight Dialog Eval: ${topAlert.message}`,
  p_description: `Detected ${alerts.length} alert(s) in last ${report.window_hours}h.\n\nMetrics:\n${JSON.stringify(report.metrics, null, 2)}\n\nAlerts:\n${alerts.map(a => `- [${a.severity}] ${a.metric}: ${a.message}`).join('\n')}`,
  p_category: 'optimization',
  p_metadata: report,
};

try {
  const response = await fetch(`${postgrestUrl}/rpc/fn_create_improvement_proposal`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${serviceKey}`,
      'apikey': serviceKey,
    },
    body: JSON.stringify(rpcBody),
  });
  const result = await response.json();
  return { json: { ok: true, status: 'proposal_created', proposal: result, report } };
} catch (e) {
  return { json: { ok: false, error: e.message, report } };
}
